-- DPÜ institutional integration catalog (controlled pilot only)
-- Generated deterministically from src/institutional-integration-reference.js.
-- No live endpoint, credential, personal record, payment or production operation is enabled.

begin;

create table if not exists public.institutional_system_registry (
  id text primary key,
  catalog_version text not null,
  seed_batch text not null,
  system_code text not null unique,
  system_name_tr text not null,
  short_name text not null,
  owner_unit text not null,
  system_category text not null,
  registry_kind text not null,
  public_url text not null check (public_url ~ '^https://'),
  source_url text not null check (source_url ~ '^https://'),
  source_basis text not null,
  verification_status text not null,
  source_checked_at timestamptz not null,
  registry_status text not null check (registry_status = 'candidate'),
  integration_contract_status text not null check (integration_contract_status = 'not_verified'),
  integration_tier text not null check (integration_tier in ('tier1', 'tier2', 'tier3')),
  myys_relevance text not null check (myys_relevance in ('core', 'supporting', 'adjacent')),
  master_data_domains jsonb not null check (jsonb_typeof(master_data_domains) = 'array' and jsonb_array_length(master_data_domains) > 0),
  master_data_boundary text not null check (length(master_data_boundary) >= 40),
  record_owner text not null,
  consumer_mode text not null,
  sync_mode text not null,
  conflict_policy text not null,
  consultation_only boolean not null default false,
  consultation_scope_note text not null,
  capabilities jsonb not null check (jsonb_typeof(capabilities) = 'array'),
  data_domains jsonb not null check (jsonb_typeof(data_domains) = 'array'),
  expected_data_classification jsonb not null check (jsonb_typeof(expected_data_classification) = 'array'),
  recommended_adapter text not null,
  scope_note text not null,
  institutional_validation_required boolean not null check (institutional_validation_required),
  public_metadata_only boolean not null check (public_metadata_only),
  real_data_enabled boolean not null default false check (not real_data_enabled),
  real_data_sent boolean not null default false check (not real_data_sent),
  secrets_stored boolean not null default false check (not secrets_stored),
  production_allowed boolean not null default false check (not production_allowed),
  is_public_reference boolean not null check (is_public_reference)
);

create table if not exists public.pilot_integration_mappings (
  id text primary key,
  catalog_version text not null,
  seed_batch text not null,
  system_id text not null references public.institutional_system_registry(id) on update cascade on delete restrict,
  flow_key text not null,
  integration_name_tr text not null,
  direction text not null check (direction in ('inbound', 'outbound', 'bidirectional')),
  myys_bounded_context text not null,
  data_objects jsonb not null check (jsonb_typeof(data_objects) = 'array' and jsonb_array_length(data_objects) > 0),
  trigger_event text not null,
  proposed_transport text not null,
  identity_key_strategy text not null,
  approval_gate text not null,
  priority text not null check (priority in ('p0', 'p1', 'p2')),
  retry_strategy text not null,
  authoritative_owner text not null,
  boundary_note text not null,
  mapping_status text not null check (mapping_status = 'design_draft'),
  institutional_validation_required boolean not null check (institutional_validation_required),
  real_data_enabled boolean not null default false check (not real_data_enabled),
  real_data_sent boolean not null default false check (not real_data_sent),
  live_request_enabled boolean not null default false check (not live_request_enabled),
  production_allowed boolean not null default false check (not production_allowed),
  is_synthetic boolean not null check (is_synthetic),
  unique (system_id, flow_key)
);

create table if not exists public.pilot_integration_scenarios (
  id text primary key,
  catalog_version text not null,
  seed_batch text not null,
  mapping_id text not null references public.pilot_integration_mappings(id) on update cascade on delete restrict,
  system_id text not null references public.institutional_system_registry(id) on update cascade on delete restrict,
  name_tr text not null,
  actor_role text not null,
  scenario_order integer not null check (scenario_order > 0),
  steps jsonb not null check (jsonb_typeof(steps) = 'array' and jsonb_array_length(steps) > 0),
  fallback_action text not null,
  success_criterion text not null,
  status text not null check (status = 'not_executed'),
  expected_result text not null check (expected_result = 'dry_run_only'),
  institutional_validation_required boolean not null check (institutional_validation_required),
  real_data_enabled boolean not null default false check (not real_data_enabled),
  real_data_sent boolean not null default false check (not real_data_sent),
  live_request_enabled boolean not null default false check (not live_request_enabled),
  production_allowed boolean not null default false check (not production_allowed),
  is_synthetic boolean not null check (is_synthetic),
  unique (mapping_id),
  unique (scenario_order)
);

create table if not exists public.pilot_integration_audit_events (
  id text primary key,
  catalog_version text not null,
  seed_batch text not null,
  scenario_id text not null references public.pilot_integration_scenarios(id) on update cascade on delete restrict,
  mapping_id text not null references public.pilot_integration_mappings(id) on update cascade on delete restrict,
  system_id text not null references public.institutional_system_registry(id) on update cascade on delete restrict,
  event_order integer not null check (event_order > 0),
  occurred_at timestamptz not null,
  actor_role text not null,
  event_type text not null,
  outcome text not null check (outcome = 'not_executed'),
  detail text not null,
  correlation_label text not null,
  institutional_validation_required boolean not null check (institutional_validation_required),
  real_data_enabled boolean not null default false check (not real_data_enabled),
  real_data_sent boolean not null default false check (not real_data_sent),
  live_request_made boolean not null default false check (not live_request_made),
  production_allowed boolean not null default false check (not production_allowed),
  has_personal_identifiers boolean not null default false check (not has_personal_identifiers),
  is_synthetic boolean not null check (is_synthetic),
  unique (scenario_id, event_order)
);

comment on table public.institutional_system_registry is 'Aday DPÜ sistem kataloğu; yalnız kamu üst verisi, sözleşme durumu doğrulanmamış ve üretim kapalıdır.';
comment on table public.pilot_integration_mappings is 'MYYS kontrollü pilot eşlemeleri; tasarım taslağıdır ve canlı istek yapmaz.';
comment on table public.pilot_integration_scenarios is 'Sentetik dry-run senaryoları; gerçek veri, ödeme veya kurumsal işlem içermez.';
comment on table public.pilot_integration_audit_events is 'Seed kaynak izi; gerçek kurumsal denetim kaydı veya canlı olay değildir.';

alter table public.institutional_system_registry enable row level security;
alter table public.pilot_integration_mappings enable row level security;
alter table public.pilot_integration_scenarios enable row level security;
alter table public.pilot_integration_audit_events enable row level security;
alter table public.institutional_system_registry force row level security;
alter table public.pilot_integration_mappings force row level security;
alter table public.pilot_integration_scenarios force row level security;
alter table public.pilot_integration_audit_events force row level security;

revoke all on table public.institutional_system_registry from public, anon, authenticated;
revoke all on table public.pilot_integration_mappings from public, anon, authenticated;
revoke all on table public.pilot_integration_scenarios from public, anon, authenticated;
revoke all on table public.pilot_integration_audit_events from public, anon, authenticated;
grant select on table public.institutional_system_registry to anon, authenticated;
grant select on table public.pilot_integration_mappings to anon, authenticated;
grant select on table public.pilot_integration_scenarios to anon, authenticated;
grant select on table public.pilot_integration_audit_events to anon, authenticated;

drop policy if exists institutional_system_registry_public_read on public.institutional_system_registry;
create policy institutional_system_registry_public_read on public.institutional_system_registry
  for select to anon, authenticated using (
    institutional_validation_required and public_metadata_only and is_public_reference
    and not real_data_enabled and not real_data_sent and not secrets_stored and not production_allowed
  );
drop policy if exists pilot_integration_mappings_public_read on public.pilot_integration_mappings;
create policy pilot_integration_mappings_public_read on public.pilot_integration_mappings
  for select to anon, authenticated using (
    institutional_validation_required and is_synthetic and not real_data_enabled
    and not real_data_sent and not live_request_enabled and not production_allowed
  );
drop policy if exists pilot_integration_scenarios_public_read on public.pilot_integration_scenarios;
create policy pilot_integration_scenarios_public_read on public.pilot_integration_scenarios
  for select to anon, authenticated using (
    institutional_validation_required and is_synthetic and not real_data_enabled
    and not real_data_sent and not live_request_enabled and not production_allowed
  );
drop policy if exists pilot_integration_audit_events_public_read on public.pilot_integration_audit_events;
create policy pilot_integration_audit_events_public_read on public.pilot_integration_audit_events
  for select to anon, authenticated using (
    institutional_validation_required and is_synthetic and not real_data_enabled
    and not real_data_sent and not live_request_made and not production_allowed and not has_personal_identifiers
  );

