on conflict (id) do update set
  (catalog_version, seed_batch, scenario_id, mapping_id, system_id, event_order, occurred_at, actor_role, event_type, outcome, detail, correlation_label, institutional_validation_required, real_data_enabled, real_data_sent, live_request_made, production_allowed, has_personal_identifiers, is_synthetic) =
  (excluded.catalog_version, excluded.seed_batch, excluded.scenario_id, excluded.mapping_id, excluded.system_id, excluded.event_order, excluded.occurred_at, excluded.actor_role, excluded.event_type, excluded.outcome, excluded.detail, excluded.correlation_label, excluded.institutional_validation_required, excluded.real_data_enabled, excluded.real_data_sent, excluded.live_request_made, excluded.production_allowed, excluded.has_personal_identifiers, excluded.is_synthetic);

create index if not exists institutional_system_registry_tier_idx on public.institutional_system_registry (integration_tier, myys_relevance);
create index if not exists institutional_system_registry_version_idx on public.institutional_system_registry (catalog_version, seed_batch);
create index if not exists pilot_integration_mappings_system_idx on public.pilot_integration_mappings (system_id, priority);
create index if not exists pilot_integration_scenarios_system_idx on public.pilot_integration_scenarios (system_id, scenario_order);
create index if not exists pilot_integration_audit_system_idx on public.pilot_integration_audit_events (system_id, occurred_at, event_order);

create or replace view public.institutional_system_catalog
with (security_invoker = true) as
select * from public.institutional_system_registry
where institutional_validation_required and public_metadata_only and is_public_reference
  and not real_data_enabled and not real_data_sent and not secrets_stored and not production_allowed;

create or replace view public.pilot_integration_mapping_catalog
with (security_invoker = true) as
select m.*, s.system_code, s.system_name_tr, s.integration_tier, s.myys_relevance
from public.pilot_integration_mappings m
join public.institutional_system_registry s on s.id = m.system_id
where m.institutional_validation_required and m.is_synthetic and not m.real_data_enabled
  and not m.real_data_sent and not m.live_request_enabled and not m.production_allowed
  and s.institutional_validation_required and not s.real_data_enabled and not s.production_allowed;

create or replace view public.pilot_integration_scenario_catalog
with (security_invoker = true) as
select c.*, s.system_code, s.system_name_tr
from public.pilot_integration_scenarios c
join public.institutional_system_registry s on s.id = c.system_id
where c.institutional_validation_required and c.is_synthetic and not c.real_data_enabled
  and not c.real_data_sent and not c.live_request_enabled and not c.production_allowed;

create or replace view public.pilot_integration_audit_catalog
with (security_invoker = true) as
select a.*, s.system_code
from public.pilot_integration_audit_events a
join public.institutional_system_registry s on s.id = a.system_id
where a.institutional_validation_required and a.is_synthetic and not a.real_data_enabled
  and not a.real_data_sent and not a.live_request_made and not a.production_allowed
  and not a.has_personal_identifiers;

revoke all on table public.institutional_system_catalog from public, anon, authenticated;
revoke all on table public.pilot_integration_mapping_catalog from public, anon, authenticated;
revoke all on table public.pilot_integration_scenario_catalog from public, anon, authenticated;
revoke all on table public.pilot_integration_audit_catalog from public, anon, authenticated;
grant select on table public.institutional_system_catalog to anon, authenticated;
grant select on table public.pilot_integration_mapping_catalog to anon, authenticated;
grant select on table public.pilot_integration_scenario_catalog to anon, authenticated;
grant select on table public.pilot_integration_audit_catalog to anon, authenticated;

commit;
